style.css:
@-moz-document domain("open.spotify.com") {
/* Background image */
    body {
        background: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAQ8AAAC6CAIAAAA/PV8bAAAgAElEQVR4AZTad3Db55U3esiyrS72TpFi7703kCgEQKKQRCV677333lnFIrF3EuyiumwV23F33JPYceIk9nod24lTnNibrOMkfIfWbu7Ofe/cmZ058xsMMIO/8MH3nOc5gDY4C4hgg7pY4G42DMnuRnFR...<BASE64 CONTINUES>...") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Make main content transparent so background shows */
    .Root__main-view,
    .Root__now-playing-bar,
    .Root__top-bar {
        background-color: rgba(0, 0, 0, 0.4) !important;
        backdrop-filter: blur(6px) !important;
    }

    /* Sidebar styling */
    .Root__nav-bar {
        background-color: rgba(0, 0, 0, 0.6) !important;
        backdrop-filter: blur(6px) !important;
    }

    /* Text color adjustments */
    * {
        color: #fff !important;
    }

    /* Remove some default shadows */
    .Root__main-view,
    .Root__top-bar {
        box-shadow: none !important;
    }
}
